// 접속코드는 인증 요청에만 사용하고 응답 후 입력란에서 지웁니다.
(() => {
 const field=document.getElementById('ai-access-code'),login=document.getElementById('practice-login'),logout=document.getElementById('practice-logout'),status=document.getElementById('practice-auth-status');
 let authenticated=false,expiresAt=null;
 function update(data,message){authenticated=!!data.authenticated;expiresAt=data.expiresAt||null;field.value='';field.hidden=authenticated;field.required=!authenticated;document.querySelector('label[for="ai-access-code"]').hidden=authenticated;login.hidden=authenticated;logout.hidden=!authenticated;status.textContent=message||(authenticated?'인증됨 · 최대 8시간 유지':'접속코드로 인증해 주세요.');document.dispatchEvent(new Event('practice-auth-change'));}
 async function refresh(){if(location.protocol==='file:'){update({authenticated:false},'로컬 서버에서 열어 주세요.');return;}try{const r=await fetch('/api/auth',{cache:'no-store',credentials:'same-origin'});if(!r.ok)throw Error();update(await r.json());}catch{update({authenticated:false},'인증 상태를 확인하지 못했습니다.');}}
 const ready=refresh();let pending=null;
 async function ensure(){await ready;if(authenticated&&expiresAt>Date.now())return true;if(pending)return pending;const accessCode=field.value.trim();if(!accessCode){update({authenticated:false});field.focus();return false;}
 pending=(async()=>{login.disabled=true;status.textContent='인증 중…';try{const r=await fetch('/api/auth',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({accessCode})});const data=await r.json();if(!r.ok)throw Error(data.error||'인증에 실패했습니다.');update(data);return true;}catch(error){update({authenticated:false},error instanceof TypeError?'서버에 연결하지 못했습니다.':error.message);field.focus();return false;}finally{login.disabled=false;pending=null;}})();return pending;}
 login.addEventListener('click',ensure);field.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();ensure();}});
 logout.addEventListener('click',async()=>{logout.disabled=true;try{const r=await fetch('/api/auth',{method:'DELETE',credentials:'same-origin'});if(!r.ok)throw Error();update({authenticated:false},'로그아웃했습니다.');for(const id of ['ai-answer','public-data-result','rag-debug','application-preview']){const e=document.getElementById(id);e.hidden=true;if(id==='public-data-result')e.replaceChildren();}for(const id of ['ai-question','application-receiptNumber','application-receiptDate','application-dataName','application-content','application-purpose','application-file'])document.getElementById(id).value='';field.focus();}catch{status.textContent='로그아웃에 실패했습니다. 다시 시도해 주세요.';}finally{logout.disabled=false;}});
 window.practiceSession={ensure,async handleResponse(response){if(response.status===401)update({authenticated:false},'인증이 만료되었거나 종료됐습니다. 접속코드를 다시 입력해 주세요.');}};
})();
